import{_ as t,c as n,o as a,ae as i}from"./chunks/framework.CHDT0Kbg.js";const f=JSON.parse('{"title":"Funktionen im Überblick","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/features.md","filePath":"de/guide/features.md","lastUpdated":1795170900000}'),r={name:"de/guide/features.md"};function d(l,e,s,u,o,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="funktionen-im-uberblick" tabindex="-1">Funktionen im Überblick <a class="header-anchor" href="#funktionen-im-uberblick" aria-label="Permalink to &quot;Funktionen im Überblick&quot;">​</a></h1><p>Ein kurzer Rundgang durch das, was du am häufigsten nutzt.</p><h2 id="taglich-surfen" tabindex="-1">Täglich surfen <a class="header-anchor" href="#taglich-surfen" aria-label="Permalink to &quot;Täglich surfen&quot;">​</a></h2><ul><li>Mehrere Tabs und Fenster: herausziehen, gruppieren, einklappen, stummschalten, Vorschau.</li><li>Die Adressleiste schlägt zuerst bekannte Seiten vor und sucht sonst im Web.</li><li>Befehlspalette (⌘K), Tabsuche (⌘⇧A), Finden auf der Seite (⌘F) und eine Tastenkürzel-Liste im Zahnradmenü.</li></ul><h2 id="angenehm-fur-die-augen" tabindex="-1">Angenehm für die Augen <a class="header-anchor" href="#angenehm-fur-die-augen" aria-label="Permalink to &quot;Angenehm für die Augen&quot;">​</a></h2><ul><li>Design: System folgen, hell oder dunkel. Dunkle Seiten und automatischer Wechsel pro Tag sind möglich.</li><li>Sechs Akzentfarben: Blau, Violett, Türkis, Grün, Orange und Rosé.</li><li>Lesezeichenleiste: immer aus, immer an oder nur im neuen Tab.</li></ul><h2 id="werbung-und-skripte" tabindex="-1">Werbung und Skripte <a class="header-anchor" href="#werbung-und-skripte" aria-label="Permalink to &quot;Werbung und Skripte&quot;">​</a></h2><ul><li>Der Werbeblocker unterstützt Abonnements, eigene Regeln und eine Erlaubnisliste. Schlägt ein Update fehl, gelten die alten Regeln weiter.</li><li>Benutzerskripte (<code>.user.js</code>) werden in den Einstellungen verwaltet und nach dem Download installiert.</li></ul><h2 id="videos-und-dateien" tabindex="-1">Videos und Dateien <a class="header-anchor" href="#videos-und-dateien" aria-label="Permalink to &quot;Videos und Dateien&quot;">​</a></h2><ul><li>Downloads lassen sich pausieren, fortsetzen, abbrechen und wiederholen. Danach im Finder zeigen oder mit der zugehörigen App öffnen.</li><li>Das Medienfenster erkennt Videos auf Seiten und fügt aufgeteilte Videos zu einer MP4 zusammen.</li></ul><h2 id="tastenkurzel" tabindex="-1">Tastenkürzel <a class="header-anchor" href="#tastenkurzel" aria-label="Permalink to &quot;Tastenkürzel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Funktion</th></tr></thead><tbody><tr><td>⌘T / ⌘W</td><td>Tab öffnen / schließen</td></tr><tr><td>⌘L</td><td>Adressleiste fokussieren</td></tr><tr><td>⌘F</td><td>Auf der Seite suchen</td></tr><tr><td>⌘⇧N</td><td>Privates Fenster</td></tr><tr><td>⌘K</td><td>Befehlspalette</td></tr><tr><td>⌘⇧A</td><td>Tabsuche</td></tr><tr><td>⌘⇧R</td><td>Lesemodus</td></tr></tbody></table>',12)])])}const b=t(r,[["render",d]]);export{f as __pageData,b as default};
